# Kutzbach: M = m*(N-1-J) + sum(f_i)   m=3 duzlem, m=6 uzay
F = {"R": 1, "P": 1, "U": 2, "S": 3, "C": 2}

def dof(m, N, joints):
    J = len(joints)
    return m * (N - 1 - J) + sum(F[j] for j in joints)

mekanizmalar = [
    ("Duzlemsel 4-cubuk", 3, 4, ["R", "R", "R", "R"]),
    ("Duzlemsel 3R kol", 3, 4, ["R", "R", "R"]),
    ("Uzaysal 6R kol", 6, 7, ["R"] * 6),
    ("Stewart platform", 6, 14, ["U"] * 6 + ["P"] * 6 + ["S"] * 6),
]
for ad, m, N, j in mekanizmalar:
    print(ad, "->", dof(m, N, j))

import math

L1, L2 = 0.40, 0.30

def ters_2r(x, y):
    """2R duzlemsel kol ters kinematigi: (dirsek yukari, dirsek asagi)"""
    r2 = x*x + y*y
    c2 = (r2 - L1*L1 - L2*L2) / (2*L1*L2)
    if abs(c2) > 1.0:
        return []
    cozumler = []
    for isaret in (+1, -1):
        t2 = isaret * math.acos(max(-1.0, min(1.0, c2)))
        t1 = math.atan2(y, x) - math.atan2(L2*math.sin(t2), L1 + L2*math.cos(t2))
        cozumler.append((round(math.degrees(t1), 4), round(math.degrees(t2), 4)))
    return cozumler

def ileri_2r(t1_deg, t2_deg):
    t1, t2 = math.radians(t1_deg), math.radians(t2_deg)
    return (round(L1*math.cos(t1) + L2*math.cos(t1+t2), 6),
            round(L1*math.sin(t1) + L2*math.sin(t1+t2), 6))

for hedef in [(0.50, 0.30), (0.70, 0.00), (0.75, 0.20)]:
    c = ters_2r(*hedef)
    print(hedef, "->", c if c else "erisilemez")
    for s in c:
        print("   dogrulama FK:", ileri_2r(*s))

import math

L_DOLU = math.log(0.7 / 0.3)    # isin sonundaki hucre
L_BOS = math.log(0.4 / 0.6)     # isin uzerindeki hucreler
L_MIN, L_MAKS = -5.0, 5.0       # doyum siniri

def olasilik(l):
    return 1.0 / (1.0 + math.exp(-l))

def guncelle(l, dolu_mu):
    l = l + (L_DOLU if dolu_mu else L_BOS)
    return max(L_MIN, min(L_MAKS, l))

print("l_dolu =", round(L_DOLU, 4), " l_bos =", round(L_BOS, 4))

l = 0.0
for k, gozlem in enumerate([True, True, True, False, False], 1):
    l = guncelle(l, gozlem)
    print(k, "dolu" if gozlem else "bos ", "l =", round(l, 4), "p =", round(olasilik(l), 4))

